        {"구절":"고전 1:18", "연결점":"십자가의 도가 멸망하는 자들에게는 미련한 것이나", "구분":"신약"},
        {"구절":"엡 3:20", "연결점":"우리가 구하거나 생각하는 것에 더 넘치도록 하시는 하나님", "구분":"신약"},
        {"구절":"롬 11:33", "연결점":"하나님의 지혜와 지식의 풍성함이여 그 판단을 헤아릴 수 없도다", "구분":"신약"}
