        {"구분":"자기를 법으로 삼는 교만", "내용":"자기 심판과 위엄을 스스로 정하는 바벨론", "그리스도연결":"자기를 낮추시고 아버지의 뜻에 순종하신 겸손한 그리스도 (빌 2:8)"},
        {"구분":"거짓 권위와 참 권위", "내용":"자기에게서 나오는 거짓 위엄을 자랑하는 바벨론", "그리스도연결":"하나님에게서 받은 참된 권위를 가지신 그리스도 (마 28:18)"}
