        {"상황":"직장 상사의 부당한 권력 행사에 고통받는 분", "성경원리":"자기에게서 나오는 위엄과 심판을 주장하는 것은 바벨론의 교만이다. 참된 권위는 하나님에게서 나온다", "실제적용":"부당한 권력에 굴복하지 말되 지혜롭게 대처하라. 최종 심판자는 하나님이시다"},
        {"상황":"자기 판단만 옳다고 생각하는 습관이 있는 분", "성경원리":"심판이 자기로 말미암는 것은 바벨론의 특징이었다. 자기 기준만 절대화하면 교만에 빠진다", "실제적용":"중요한 결정 전에 하나님의 말씀과 신뢰하는 사람들의 조언을 구하라"},
        {"상황":"권위에 대한 거부감이 있는 분", "성경원리":"모든 권위는 하나님에게서 나온다(롬 13:1). 합당한 권위를 존중하는 것은 하나님을 존중하는 것이다", "실제적용":"거짓 권위와 참된 권위를 분별하라. 하나님이 세우신 합당한 권위는 존중하라"}
