    표5_매튜헨리: [
        {"영어원문":"Their horses are swifter than leopards — nothing can escape them; and fiercer than evening wolves that come out hungry for prey.", "한국어번역":"그들의 말은 표범보다 빠르니 아무것도 그들을 피할 수 없고, 먹이를 찾아 굶주려 나오는 저녁 이리보다 사납다.", "핵심통찰":"하나님의 심판 도구는 빠르고 피할 수 없다"},
        {"영어원문":"They shall fly as the eagle that hasteth to eat — with the same swiftness and greediness do the Chaldean soldiers seize their prey.", "한국어번역":"먹이를 움키려는 독수리같이 날으리니 — 갈대아 군사들이 같은 속도와 탐욕으로 먹이를 움켜잡는다.", "핵심통찰":"심판은 독수리처럼 빠르고 확실하게 임한다"},
        {"영어원문":"Those who make themselves a prey to their own lusts will soon be made a prey to their enemies.", "한국어번역":"자기 욕심의 먹이가 된 자들은 곧 적의 먹이가 될 것이다.", "핵심통찰":"죄의 결과로 오는 심판은 피할 수 없다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"표범보다 빠른 심판 - 바벨론 군대의 비유", "예화_적용":"하나님의 심판은 얼마나 빠르고 확실한가"},
        {"대지":"서론", "내용":"하나님은 바벨론 군대를 네 가지 맹수에 비유하셨다. 표범의 속도, 저녁 이리의 사나움, 원방 기병의 기동력, 독수리의 급습. 이 생생한 비유는 심판의 실체를 눈앞에 펼쳐 보여준다", "예화_적용":"다큐멘터리에서 치타가 가젤을 추격하는 장면처럼, 하나님의 심판은 빠르고 확실하다"},
        {"대지":"1대지: 표범보다 빠른 말 (심판의 속도)", "내용":"표범은 시속 100km로 달리는 가장 빠른 육상 동물이다. 바벨론 기병은 이보다 빠르다고 묘사된다. 심판은 예상보다 빠르게 온다", "예화_적용":"'내일 하지 뭐'라고 미루는 사이에 기회는 지나간다. 회개도 마찬가지이다"},
        {"대지":"2대지: 저녁 이리보다 사나운 기병 (심판의 강도)", "내용":"저녁 이리는 하루 종일 굶주려 가장 사나운 상태의 이리이다. 바벨론의 사나움은 굶주린 맹수와 같았다", "예화_적용":"단 하루만 굶어도 사나워지는 동물처럼, 탐욕에 사로잡힌 자는 무엇이든 삼키려 한다"},
        {"대지":"3대지: 독수리처럼 급습하는 침략 (심판의 피할 수 없음)", "내용":"독수리는 높은 하늘에서 먹이를 발견하고 단숨에 내리꽂는다. 하나님의 심판도 이처럼 피할 수 없다", "예화_적용":"독수리의 시력은 인간의 8배이다. 아무리 숨어도 하나님의 눈을 피할 수 없듯, 심판도 피할 수 없다"},
        {"대지":"결론", "내용":"네 가지 맹수의 비유는 하나님의 심판이 빠르고 사납고 피할 수 없음을 보여준다. 그러나 이 심판은 멸절이 아닌 훈련을 위함이다. 오늘 회개하고 하나님께 돌아오는 자에게는 은혜가 있다", "예화_적용":"의사가 수술이 급하다고 말할 때 미루지 말아야 하듯, 하나님의 경고 앞에서 회개를 미루지 말자"}
    ],
