        {"구절":"마 24:27", "연결점":"번개가 동편에서 나서 서편까지 번쩍이듯 인자의 임함도 그러하리라", "구분":"신약"},
        {"구절":"살전 5:2-3", "연결점":"도적같이 이르리라 평안하다 할 때에 멸망이 홀연히 임하리니", "구분":"신약"},
        {"구절":"계 19:11-14", "연결점":"하늘이 열리니 백마를 탄 이가 나타나시니 충신과 진실이라", "구분":"신약"},
        {"구절":"벧후 3:10", "연결점":"주의 날이 도적같이 오리니", "구분":"신약"}
