        {"구절":"눅 4:18", "연결점":"사로잡힌 자에게 자유를 갇힌 자에게 놓임을 전파하게 하시려고", "구분":"신약"},
        {"구절":"롬 8:28", "연결점":"모든 것이 합력하여 선을 이루느니라", "구분":"신약"},
        {"구절":"계 13:10", "연결점":"사로잡히는 자는 사로잡힐 것이니 — 성도의 인내", "구분":"신약"}
