        {"구절":"마 16:18", "연결점":"음부의 권세가 이기지 못하리라 — 교회의 견고함", "구분":"신약"},
        {"구절":"고후 10:4", "연결점":"우리의 싸우는 병기는 견고한 진을 파하느니라", "구분":"신약"},
        {"구절":"계 19:16", "연결점":"만왕의 왕이요 만주의 주라 — 모든 권위 위의 권위", "구분":"신약"},
        {"구절":"히 11:10", "연결점":"하나님이 계획하시고 지으신 터가 있는 성을 바라는 믿음", "구분":"신약"}
