        {"구절":"단 4:30-33", "연결점":"이 큰 바벨론은 내가 세운 것이 아니냐 — 느부갓네살의 교만과 심판", "구분":"구약"},
        {"구절":"사 10:12-15", "연결점":"도끼가 자기로 찍는 자에게 스스로 큰 체 하겠느냐", "구분":"구약"},
        {"구절":"겔 28:2", "연결점":"네 마음이 높아져서 나는 신이라 하였도다 — 두로 왕의 교만", "구분":"구약"},
        {"구절":"요 15:5", "연결점":"나를 떠나서는 너희가 아무것도 할 수 없느니라", "구분":"신약"},
        {"구절":"약 4:6", "연결점":"하나님이 교만한 자를 물리치시고 겸손한 자에게 은혜를 주시느니라", "구분":"신약"},
        {"구절":"고전 4:7", "연결점":"받은 것이 아닌 것이 무엇이냐 받았은즉 어찌하여 자랑하느냐", "구분":"신약"},
        {"구절":"행 12:23", "연결점":"헤롯이 하나님께 영광을 돌리지 아니하므로 벌레에게 먹혀 죽으니라", "구분":"신약"}
