        {"구분":"사망에 이르지 않을 것이라는 확신", "내용":"하나님의 백성은 심판 가운데서도 완전히 멸망하지 않음", "그리스도연결":"사망을 이기시고 부활하신 그리스도로 인해 사망이 삼키운 바 된 것 (고전 15:54-57)"},
        {"구분":"심판을 위해 세워진 도구", "내용":"하나님이 심판 목적으로 바벨론을 세우심", "그리스도연결":"하나님이 만국의 심판자로 세우신 그리스도 (행 17:31, 요 5:22)"}
