        {"상황":"변화무쌍한 환경에 불안한 분", "성경원리":"하나님은 반석(추르)이시다. 세상은 변하지만 하나님은 변하지 않으신다", "실제적용":"변하는 환경에 흔들리지 말고 변하지 않는 하나님의 약속에 뿌리를 내리라"}
