        {"구분":"그물을 떨고 다시 사용하는 탐욕", "내용":"끝없는 정복욕에 사로잡힌 바벨론", "그리스도연결":"자기 것을 다 버리시고 우리에게 주신 그리스도의 자기 비움 (빌 2:7)"},
        {"구분":"옳으니이까 — 공의를 향한 호소", "내용":"하나님의 공의에 대한 하박국의 마지막 호소", "그리스도연결":"십자가에서 완성하신 하나님의 궁극적 공의 (롬 3:25-26)"}
