    표5_매튜헨리: [
        {"영어원문":"Shall they therefore empty their net and not spare continually to slay the nations? — shall this go on forever?", "한국어번역":"그들이 그물을 비우고 열국을 살륙하기를 계속하는 것이 옳으니이까? — 이것이 영원히 계속될 것인가?", "핵심통찰":"악의 반복에 대한 하나님의 최종 심판을 구하는 질문이다"},
        {"영어원문":"The prophet's question is not a complaint against God but an appeal to his justice — surely this cannot continue.", "한국어번역":"선지자의 질문은 하나님에 대한 불평이 아니라 그분의 공의에 대한 호소이다 — 분명히 이것은 계속될 수 없다.", "핵심통찰":"하나님의 공의에 호소하는 것은 하나님의 성품을 신뢰하는 표현이다"},
        {"영어원문":"God's patience is not endless indulgence; in due time he will call the oppressor to account.", "한국어번역":"하나님의 인내는 끝없는 방임이 아니다. 때가 되면 압제자에게 결산을 요구하실 것이다.", "핵심통찰":"하나님의 인내에는 목적이 있으며 때가 되면 반드시 공의를 세우신다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"그물을 떨고 다시 - 끝나지 않는 악 앞에서의 믿음", "예화_적용":"악이 반복될 때 성도는 어떤 자세를 취해야 하는가"},
        {"대지":"서론", "내용":"하박국 1장의 마지막 질문이다. 바벨론은 그물로 잡고, 비우고, 다시 잡기를 반복한다. 끝없는 살륙이 계속된다. 하박국은 묻는다 — 이것이 옳으니이까? 이 질문의 답은 2장에서 주어진다", "예화_적용":"전쟁이 끝나자마자 또 다른 전쟁이 시작되는 역사를 보면 하박국의 질문이 이해된다"},
        {"대지":"1대지: 그물을 떨고 다시 사용함 (탐욕의 무한 반복)", "내용":"그물을 비워 다시 사용하는 것은 탐욕이 결코 만족하지 않음을 보여준다. 하나를 얻으면 둘을, 둘을 얻으면 셋을 원한다", "예화_적용":"알렉산더 대왕은 세계를 정복한 후 '더 이상 정복할 땅이 없다'며 울었다고 한다. 탐욕은 결코 만족하지 않는다"},
        {"대지":"2대지: 늘 열국을 살륙함 (반복되는 악)", "내용":"'타미드'(늘, 계속)는 바벨론의 폭력이 일회적이 아닌 반복적임을 강조한다. 악은 스스로 멈추지 않는다", "예화_적용":"중독이 한 번으로 끝나지 않듯, 악도 한 번으로 끝나지 않는다. 오직 하나님의 개입만이 악의 반복을 멈출 수 있다"},
        {"대지":"3대지: 옳으니이까 - 공의를 향한 호소 (하나님의 답을 기다림)", "내용":"'옳으니이까'는 하박국의 마지막 질문이다. 이것은 하나님의 공의가 반드시 실현될 것이라는 믿음의 표현이다", "예화_적용":"법정에서 판사에게 '이것이 정의입니까?'라고 묻는 것은 판사의 공정성을 신뢰하기에 가능한 질문이다"},
        {"대지":"결론", "내용":"하박국 1장은 질문으로 시작하여 더 깊은 질문으로 끝난다. 그러나 이 질문은 2장의 위대한 답 — '의인은 믿음으로 살리라' — 를 향한 준비이다. 질문하는 믿음이 답을 얻는 믿음으로 성장한다", "예화_적용":"하박국의 '옳으니이까'는 절망의 외침이 아니라 소망의 기도이다. 하나님은 반드시 답하신다"}
    ],
