        {"새찬송가":"234", "통일찬송가":"234", "제목":"성경에 진리 옥같이", "선정이유":"기록된 성경의 진리를 찬양하는 찬송"},
        {"새찬송가":"541", "통일찬송가":"459", "제목":"주의 말씀 듣고서", "선정이유":"하나님의 말씀을 듣고 순종하는 응답"},
        {"새찬송가":"235", "통일찬송가":"235", "제목":"만복의 근원 하나님", "선정이유":"하나님의 계시의 은혜에 감사하는 찬송"}
