        {"상황":"조급함으로 잘못된 결정을 할 위험이 있는 분", "성경원리":"'비록 더딜지라도 기다리라'는 명령은 조급함의 위험을 경고한다. 하나님의 때가 최선의 때이다", "실제적용":"조급한 결정을 피하고 하나님의 때를 기다리라. 사라처럼 조급하면 이스마엘이 태어난다"}
