        {"영어원문":"Wine is a mocker, and it mocks those who are addicted to it, betraying them into all manner of extravagances.", "한국어번역":"술은 조롱하는 것이니, 술에 빠진 자를 조롱하여 온갖 방탕으로 이끈다.", "핵심통찰":"쾌락에 빠진 자는 판단력을 잃고 파멸로 향한다"},
        {"영어원문":"He gathers unto him all nations — but he gathers them for his own destruction, not for their good.", "한국어번역":"만국을 자기에게로 모으나 — 그것은 선을 위해서가 아니라 자기 파멸을 위해 모으는 것이다.", "핵심통찰":"탐욕으로 모은 것은 결국 자기 파멸의 원인이 된다"}
